from pathlib import Path
import argparse,collections,json,hashlib

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--stage',type=Path,required=True);ap.add_argument('--prior-review-dir',type=Path,required=True);ap.add_argument('--review-dir',type=Path,required=True);a=ap.parse_args();d=a.review_dir;r=json.loads((d/'all-finite-review.json').read_text());old=json.loads((a.prior_review_dir/'delivery-manifest.json').read_text());proof=json.loads((d/'editorial-and-options-review.json').read_text());pairs=json.loads((d/'opposite-pair-review.json').read_text());assert r['candidateArtifactSHA256']==sha(a.stage/'candidates.json');assert not r['failures'];assert pairs['counts']=={'records':163,'mathematicalPairs':0,'literalPairs':0}
 out={**old,'status':'stage14-source-bound-independent-review-complete','sourceCandidateSHA256':r['candidateArtifactSHA256'],'priorManifestSHA256':sha(a.prior_review_dir/'delivery-manifest.json'),'counts':r['counts'],'evidenceReuse':{'unchangedRecords':155,'independentlyRecheckedGaussMenus':8,'newGaussPairCertificates':48,'statementAnswerSolutionLevelLineageUnchanged':True},'replicated65PercentOptionFlags':[g['familyId']for g in proof['groups']if g['replicated65PercentRules']],'reproduce':'Run review-code/rebind_stage14.py with --prior-stage --stage --prior-review-dir --out; then write_editorial_review.py, opposite_review.py and finalize_stage14.py using their explicit CLI paths. No author constructor is imported.','GaussOptionQualification':'The ignore-divisibility distractor also truncates a noninteger reduced linear coefficient in its erroneous arithmetic; this is explicitly disclosed in the peer report. The correct route enforces divisibility before reduction. All four choices per case are distinct nonnegative integers; a second square remains whenever the correct value is square, and the elementary orthogonality upper bound leaves at least two candidates.','files':{str(p.relative_to(d)):sha(p)for p in sorted(d.rglob('*'))if p.is_file()and p.name!='delivery-manifest.json'}}
 (d/'delivery-manifest.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'manifestSHA256':sha(d/'delivery-manifest.json'),'sourceCandidateSHA256':out['sourceCandidateSHA256'],'counts':out['counts'],'advancedRaw':out['advancedRawInReviewedScope'],'advancedNormalized':out['advancedNormalizedInReviewedScope']}))
